import argparse
import xml.etree.ElementTree as ET
import sys
import threading
import queue
from collections import defaultdict

class PoolRunner:
    def __init__(self, config_path):
        self.config_path = config_path
        self.pools = self._parse_config()
        self.running_commands = defaultdict(int)
        self.command_queue = queue.Queue()
        self.lock = threading.Lock()
        self.exit_flag = False

    def _parse_config(self):
        tree = ET.parse(self.config_path)
        root = tree.getroot()
        pools = {}
        for pool_elem in root.findall('pool'):
            name = pool_elem.get('name')
            limit = int(pool_elem.get('limit'))
            commands = []
            for cmd_elem in pool_elem.findall('command'):
                commands.append(cmd_elem.text)
            pools[name] = {'commands': commands, 'limit': limit}
        return pools

    def _run_command(self, pool_name, command):
        with self.lock:
            if self.running_commands[pool_name] >= self.pools[pool_name]['limit']:
                self.command_queue.put((pool_name, command))
                return
            self.running_commands[pool_name] += 1

        def execute():
            try:
                result = subprocess.run(command, shell=True, check=True,
                                      stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                      text=True)
                with self.lock:
                    self.running_commands[pool_name] -= 1
                for line in result.stdout.splitlines():
                    print(f"{pool_name}\t{line}")
                for line in result.stderr.splitlines():
                    print(f"{pool_name}\t{line}")
            except subprocess.CalledProcessError as e:
                with self.lock:
                    self.running_commands[pool_name] -= 1
                print(f"{pool_name}\tCommand failed with exit code {e.returncode}")
                sys.exit(1)

        thread = threading.Thread(target=execute)
        thread.start()

    def _process_queue(self):
        while True:
            with self.lock:
                if not self.command_queue.empty():
                    pool_name, command = self.command_queue.get()
                    self._run_command(pool_name, command)
                else:
                    break

    def run(self):
        import subprocess
        while True:
            line = sys.stdin.readline().strip()
            if not line:
                break
            if line in self.pools:
                for cmd in self.pools[line]['commands']:
                    self._run_command(line, cmd)
            else:
                print(f"Unknown pool: {line}", file=sys.stderr)
                sys.exit(1)

        self._process_queue()
        with self.lock:
            for pool in self.pools:
                if self.running_commands[pool] > 0:
                    print("Waiting for remaining commands to finish", file=sys.stderr)
                    self._process_queue()
        sys.exit(0)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('config_path')
    args = parser.parse_args()

    runner = PoolRunner(args.config_path)
    runner.run()

if __name__ == "__main__":
    main()

import argparse
import sys
import xml.etree.ElementTree as ET
from concurrent.futures import ThreadPoolExecutor, as_completed
from threading import Lock

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    pools = {}
    for pool_elem in root.findall('pool'):
        name = pool_elem.get('name')
        limit = int(pool_elem.get('limit'))
        commands = [cmd.text for cmd in pool_elem.findall('command')]
        pools[name] = {'limit': limit, 'commands': commands}
    return pools

def run_pool(pool_name, commands, limit, output_lock):
    with ThreadPoolExecutor(max_workers=limit) as executor:
        futures = []
        for cmd in commands:
            future = executor.submit(lambda: run_command(cmd), output_lock)
            futures.append(future)

        for future in as_completed(futures):
            try:
                future.result()
            except Exception:
                pass

def run_command(cmd):
    import subprocess
    process = subprocess.Popen(
        cmd.split(),
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        text=True
    )
    while True:
        output = process.stdout.readline()
        if output == '' and process.poll() is not None:
            break
        if output:
            yield output.strip()

def process_pool(pool_name, pool_data, output_lock):
    commands = pool_data['commands']
    limit = pool_data['limit']
    for cmd_output in run_pool(pool_name, commands, limit, output_lock):
        with output_lock:
            print(f"{pool_name}\t{cmd_output}")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('config', help='XML configuration file path')
    args = parser.parse_args()

    pools = parse_xml(args.config)
    output_lock = Lock()

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        if line in pools:
            process_pool(line, pools[line], output_lock)

    # Wait for all running commands to finish
    for pool_name in pools:
        process_pool(pool_name, pools[pool_name], output_lock)

if __name__ == "__main__":
    main()
